const Campaign=window.UBCampaign,H=window.UBHarbor;
const {Game,HULLS,CAPTAINS,CREWS,WEAPONS,RARITIES,ARTIFACTS,EVOLUTIONS,PRESSURES,RESEARCH,BIOMES,freshMeta,sanitizeMeta,purchaseResearch,researchCost,clamp}=window.Underburg;
const $=id=>document.getElementById(id),sound=new Soundscape();let game=null,meta=freshMeta(),selected={hull:'nautilus',captain:'greta',crew:'divers',weapon:'torpedo',pressure:'survey'},keys=new Set(),pointer=null,boostHeld=false,last=0,elapsed=0,wasState='menu',hudT=0,toastUntil=0,modalKind='',draftStamp='',settlement=0,pausedForHelp=false,view,atlas,savedRun=null,saveAt=0,campaign=Campaign.freshCampaign(),campaignBonus=0,harborState=H.freshHarbor(),harborUI=null,harborOrigin='menu',earnedAchievements=[],expeditionUI=null;
try{meta=sanitizeMeta(JSON.parse(localStorage.getItem('underburg.meta.v2')));const s=JSON.parse(localStorage.getItem('underburg.loadout.v2'));if(s&&typeof s==='object')for(const [key,table]of Object.entries({hull:HULLS,captain:CAPTAINS,crew:CREWS,weapon:WEAPONS,pressure:PRESSURES}))if(table[s[key]])selected[key]=s[key];sound.enabled=localStorage.getItem('underburg.sound')!=='off';}catch{}
try{const raw=JSON.parse(localStorage.getItem('underburg.run.v3'));const restored=Game.restore(raw);if(restored&&!meta.settled.includes(restored.runId))savedRun=raw;}catch{}
try{campaign=Campaign.sanitizeCampaign(JSON.parse(localStorage.getItem('underburg.campaign.v1')));}catch{}
try{harborState=H.sanitizeHarbor(JSON.parse(localStorage.getItem('underburg.harbor.v1')));}catch{}
H.syncProgress(harborState,meta,campaign);selected=H.resolveLoadout(harborState,selected);
const DEFAULT_BINDINGS=['KeyQ','KeyE','KeyR','KeyF','KeyC','KeyV','KeyX'],BINDING_STORAGE='underburg.bindings.v1';
const RESERVED_BINDINGS=new Set(['KeyW','KeyA','KeyS','KeyD','KeyB','KeyM','KeyG','KeyT','Space','ShiftLeft','ShiftRight','Escape','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Digit1','Digit2','Digit3','Digit4','Digit5','Digit6']);
const validBinding=code=>typeof code==='string'&&/^(Key[A-Z]|Digit[0789])$/.test(code)&&!RESERVED_BINDINGS.has(code);
let bindings=DEFAULT_BINDINGS.slice(),bindingCapture=-1,controlsExit=null;
try{const stored=JSON.parse(localStorage.getItem(BINDING_STORAGE));if(Array.isArray(stored)&&stored.length===7&&stored.every(code=>validBinding(code)||code==='KeyG'||code==='KeyT')&&new Set(stored).size===7){bindings=stored.slice();for(let i=0;i<bindings.length;i++)if(!validBinding(bindings[i]))bindings[i]=[DEFAULT_BINDINGS[i],...DEFAULT_BINDINGS,'KeyH','KeyY','KeyZ','KeyU','KeyI','KeyO','KeyP'].find(code=>validBinding(code)&&!bindings.includes(code));if(bindings.some((code,i)=>code!==stored[i]))localStorage.setItem(BINDING_STORAGE,JSON.stringify(bindings));}}catch{}
const bindingLabel=code=>code.replace(/^Key|^Digit/,'');
const activeKeys=()=>bindings.slice(0,6).map(bindingLabel).join(' / ');
function saveBindings(){try{localStorage.setItem(BINDING_STORAGE,JSON.stringify(bindings));}catch{}syncBindingHints();if(game)syncModules();}
function syncBindingHints(){document.querySelectorAll('[data-active-keys]').forEach(e=>e.textContent=activeKeys());document.querySelectorAll('[data-all-key]').forEach(e=>e.textContent=bindingLabel(bindings[6]));}
function movementHint(){return 'WASD / arrows steer · Shift boosts · Space emits sonar · '+activeKeys()+' trigger slots 1–6 · '+bindingLabel(bindings[6])+' fires every ready ability · B opens upgrades · G interacts · T opens the survey chart.';}
function controlsStatus(text,error=false){const status=$('binding-status');if(status){status.textContent=text;status.classList.toggle('binding-error',error);}}
function cancelBinding(){if(bindingCapture<0)return;bindingCapture=-1;document.querySelectorAll('[data-binding]').forEach(b=>b.classList.remove('listening'));controlsStatus('Assignment cancelled. Select a key to change it.');}
function renderBindings(){
 $('choices').className='binding-grid';$('choices').innerHTML='';
 bindings.forEach((code,i)=>{const row=document.createElement('div');row.className='binding-row';const label=document.createElement('div');label.className='binding-label';const title=document.createElement('strong');title.textContent=i===6?'All ready abilities':'Active ability '+(i+1);const detail=document.createElement('small');detail.textContent=i===6?'Triggers every mounted system':game?.moduleOrder[i]?WEAPONS[game.moduleOrder[i]].name:'Weapon hardpoint '+(i+1);label.append(title,detail);const button=document.createElement('button');button.className='binding-key';button.dataset.binding=i;button.textContent=bindingLabel(code);button.setAttribute('aria-label','Rebind '+(i===6?'all ready abilities':'active ability '+(i+1))+', currently '+bindingLabel(code));button.onclick=()=>{bindingCapture=i;document.querySelectorAll('[data-binding]').forEach(b=>b.classList.toggle('listening',Number(b.dataset.binding)===i));controlsStatus('Press a new key for '+(i===6?'all ready abilities':'active ability '+(i+1))+'. Escape cancels.');};const alias=document.createElement('span');alias.className='binding-alias';alias.textContent=i===6?'SALVO':(i+1)+' ALSO WORKS';row.append(label,button,alias);$('choices').append(row);});
}
function showControls(origin='header'){
 const resume=game?.state==='playing',helpResume=pausedForHelp;if(resume){game.state='paused';checkpoint();}
 showModal('controls','STEERING STATION / TASTENBELEGUNG','Keep your hands <em>on the helm.</em>','Six active abilities sit beside WASD. Select any key below, then press its replacement. Changes are saved automatically.');
 controlsExit=()=>{bindingCapture=-1;if(origin==='pause'&&game){game.state='playing';pause();}else if(origin==='help'){if(helpResume&&game)game.state='playing';help();}else{closeModal();if(resume&&game)game.state='playing';}};
 $('modal-info').innerHTML='<div class="fixed-bindings"><span><kbd>WASD / ↑↓←→</kbd> STEER</span><span><kbd>SHIFT</kbd> BOOST</span><span><kbd>SPACE</kbd> SONAR</span></div><p id="binding-status" role="status" aria-live="polite">Select a key to change it. Number keys 1–6 always remain available.</p><p class="binding-note">Movement, B (upgrades), G (interact), T (survey), M (sound), Escape, and 1–6 are reserved. Use a letter or 0, 7, 8, 9. Each action needs its own key. Bindings use physical key positions.</p>';
 renderBindings();action('DONE',()=>controlsExit(),true);action('RESET DEFAULTS',()=>{bindingCapture=-1;bindings=DEFAULT_BINDINGS.slice();saveBindings();renderBindings();controlsStatus('Default keys restored: Q / E / R / F / C / V. X fires every ready ability.');});focusModal();
}
function captureBinding(e){
 if(bindingCapture<0)return false;
 if(e.code==='Tab'){cancelBinding();return true;}
 e.preventDefault();e.stopPropagation();if(e.repeat)return true;
 if(e.code==='Escape'){cancelBinding();return true;}
 if(e.ctrlKey||e.altKey||e.metaKey||e.shiftKey||!validBinding(e.code)){controlsStatus('That key is reserved. Choose an unused letter or 0, 7, 8, 9.',true);return true;}
 const slot=bindings.indexOf(e.code);if(slot>=0&&slot!==bindingCapture){controlsStatus(bindingLabel(e.code)+' already activates '+(slot===6?'all ready abilities':'ability '+(slot+1))+'. Choose a different key.',true);return true;}
 const i=bindingCapture;bindings[i]=e.code;bindingCapture=-1;saveBindings();renderBindings();document.querySelector('[data-binding="'+i+'"]').focus();controlsStatus((i===6?'All ready abilities':'Ability '+(i+1))+' is now bound to '+bindingLabel(e.code)+'.');return true;
}
function save(){try{localStorage.setItem('underburg.meta.v2',JSON.stringify(meta));localStorage.setItem('underburg.loadout.v2',JSON.stringify(selected));localStorage.setItem('underburg.campaign.v1',JSON.stringify(campaign));localStorage.setItem('underburg.harbor.v1',JSON.stringify(harborState));}catch{}}
function checkpoint(){if(!game)return;try{if(['lost','won'].includes(game.state)){localStorage.removeItem('underburg.run.v3');savedRun=null;}else{savedRun=game.snapshot();localStorage.setItem('underburg.run.v3',JSON.stringify(savedRun));}}catch{}saveAt=elapsed+5;}
function toast(text,time=4){$('toast').textContent=text;toastUntil=elapsed+time;$('toast').style.opacity='1';}
function flash(color='#a9efcf'){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const e=$('cinematic-flash');e.style.background=color;e.animate([{opacity:.15},{opacity:0}],{duration:550,easing:'ease-out'});}
function fmt(t){return Math.floor(t/60).toString().padStart(2,'0')+':'+Math.floor(t%60).toString().padStart(2,'0');}
function showModal(kind,kicker,title,desc){modalKind=kind;keys.clear();pointer=null;boostHeld=false;const m=$('modal');m.classList.remove('hidden');m.classList.remove('universe-reward');m.classList.toggle('reward-draft',kind==='draft');delete m.dataset.draftKind;m.classList.toggle('reward-reveal',['draft','sector','end'].includes(kind));$('modal-kicker').textContent=kicker;$('modal-title').innerHTML=title;$('modal-desc').textContent=desc;$('modal-info').innerHTML='';$('choices').className='';$('choices').innerHTML='';$('modal-actions').innerHTML='';}
function closeModal(){bindingCapture=-1;$('modal').classList.add('hidden');modalKind='';keys.clear();pointer=null;boostHeld=false;$('choices').innerHTML='';$('modal-actions').innerHTML='';if(atlas?.active)atlas.refresh(campaign,{...selected,appearance:H.getLoadout(harborState)},meta);}
function action(label,fn,primary=false,disabled=false){const b=document.createElement('button');b.textContent=label;b.className=primary?'primary':'secondary';b.disabled=disabled;b.onclick=fn;$('modal-actions').append(b);return b;}
function focusModal(){const b=$('choices').querySelector('button:not(:disabled)')||$('modal-actions').querySelector('button:not(:disabled)');b?.focus();}
function card({key,name,english,desc,icon,rarity='common',tag='',price='',disabled=false,onclick,selected=false,model=null,interactive=true}){
 const reward=modalKind==='draft',b=document.createElement(interactive?'button':'article');b.className='choice'+(selected?' selected':'')+(reward?' reward-card':'');b.dataset.choice=key;b.dataset.rarity=rarity;b.style.setProperty('--rarity',RARITIES[rarity]?.color||'#a4d7bb');b.style.setProperty('--deal-index',$('choices').children.length);b.disabled=disabled;
 const copy='<span class="rarity">'+(RARITIES[rarity]?.name||rarity)+'</span><strong>'+name+'</strong>'+(english?'<span class="english">'+english+'</span>':'')+'<p>'+desc+'</p><span class="tag">'+tag+'</span>'+(price?'<span class="price">'+price+'</span>':'');b.innerHTML='<span class="choice-icon">'+icon+'</span>'+(reward?'<div class="reward-copy">'+copy+'</div>':copy);
 if(model&&view){const url=reward&&view.cardPortrait?view.cardPortrait(model):view.thumbnail(model);if(url){const img=document.createElement('img');img.src=url;img.alt='';img.className='model-portrait';b.querySelector('.choice-icon').replaceChildren(img);b.classList.add('has-model');}}
 if(onclick)b.onclick=onclick;if(reward){b.onpointerenter=b.onfocus=()=>sound.event({type:'cardFocus',rarity});} $('choices').append(b);return b;
}
function applyLook(){const look=H.getLoadout(harborState);view?.setMenuHull(selected.hull,look);if(atlas?.active)atlas.refresh(campaign,{...selected,appearance:look},meta);}
function showHarbor(tab='shop'){if(!harborUI||view.loading||game&&!['won','lost'].includes(game.state))return;harborOrigin=atlas?.active?'atlas':'menu';atlas?.hide();closeModal();game=null;view.setGame(null);view.harborPreview=true;applyLook();$('menu').classList.add('hidden');$('hud').classList.add('hidden');$('pause').classList.add('hidden');wasState='harbor';harborUI.show(harborState,meta,campaign,tab);sound.start();}
