 document.querySelectorAll('[data-weapon]').forEach(b=>{const m=g.modules[b.dataset.weapon],s=g.weaponStats(b.dataset.weapon);b.disabled=g.state!=='playing'||m.active>0;b.classList.toggle('ready',m.active<=0);b.querySelector('small').textContent=m.active>0?Math.ceil(m.active)+'s RECHARGING':'ACTIVE READY';b.querySelector('.cooldown').style.width=clamp((1-m.active/s.active)*100,0,100)+'%';});$('combo').classList.toggle('hidden',g.combo<5);$('combo').textContent=g.combo+' SUNK / UNBROKEN';
 let target=b||expeditionUI?.target(g);let label=b?(b.bossName||g.biome.boss):target?.name;if(!target){let d=Infinity;for(const prop of g.props){if(prop.used||prop.kind!=='chest')continue;const q=Math.hypot(prop.x-p.x,prop.y-p.y);if(q<d){d=q;target=prop;label='SEALED VAULT';}}}const marker=$('nav-marker');if(target){let point=view.project(target.x,target.y,7),d=Math.hypot(target.x-p.x,target.y-p.y);const xx=clamp(point.x,90,innerWidth-110),yy=clamp(point.y,205,innerHeight-245);marker.style.left=xx+'px';marker.style.top=yy+'px';marker.textContent=label+' · '+Math.round(d)+'m';marker.style.color=b?'#efa28d':'#ebc989';marker.style.display=d<80?'none':'block';}else marker.style.display='none';radar();
